diff:
--- a/rtl/token_bucket.v
+++ b/rtl/token_bucket.v
@@ -34,10 +34,12 @@
     // Refill timer: one token every `rate` cycles
     // ------------------------------------------------------------------
-    assign refill = (timer == rate - 1'b1);
+    assign refill = (rate != 0) && (timer >= rate - 1'b1);

     always @(posedge clk or negedge rst_n) begin
         if (!rst_n)
             timer <= {RW{1'b0}};
-        else if (refill)
+        else if (rate == 0)
+            timer <= {RW{1'b0}};
+        else if (timer >= rate - 1'b1)
             timer <= {RW{1'b0}};
         else
@@ -53,9 +55,7 @@

     always @(*) begin
-        tokens_nx = tokens;
-        if (refill && tokens_nx != CAP_V)
-            tokens_nx = tokens_nx + 1'b1;
-        if (grant)
-            tokens_nx = tokens_nx - 1'b1;
+        tokens_nx = tokens - grant + refill;
+        if (tokens_nx > CAP_V)
+            tokens_nx = CAP_V;
     end
